#!/usr/bin/env python3
"""Shard C (UNTRUSTED helper): read the committed Lean netlist (Formal/Target/NetPS, generated by
tools-A/target/gen_lean.py) back into the JSON shape the cview tools use, so they run on exactly the
gates Lean has (no prjxray-db needed).
usage: lean2json.py lean/Formal/Target/NetPS net.json bnd.json
net.json: {"nodes": [...], "gates": [{"name","k","init","ins","arcs":[{fmin,fmax,smin,smax}],"out"}]}
bnd.json: {"boundary": {rst, req, a_ack, a_data, b_ack, b_data, start_ack, out0_req, out0_ack,
           out0_data, pend_ack}, "env": [...], "arbs": [{"q", "ins"}]}   (node names)"""
import re, sys, os, glob, json
D, onet, obnd = sys.argv[1:4]
names = []
txt = open(os.path.join(D, "Nodes.lean")).read()
for m in re.finditer(r'def n\d+ : List String := \[(.*?)\]\n', txt, re.S):
    names += [json.loads(s) for s in re.findall(r'"(?:[^"\\]|\\.)*"', m.group(1))]
S = r'"((?:[^"\\]|\\.)*)"'
pP = re.compile(r'^  P ' + S + r' (\d+) (\d+) (\d+) (\d+) (\d+) (\d+)[,\]]?$')
pG = re.compile(r'^  ⟨' + S + r', (\d+), (\d+), \[([\d, ]*)\], \[(.*?)\], (\d+)⟩[,\]]?$')
gates = []
for f in sorted(glob.glob(os.path.join(D, "G[0-9][0-9][0-9].lean"))):
    for ln in open(f):
        ln = ln.rstrip("\n")
        m = pP.match(ln)
        if m:
            n, i, o, a, b, c, d = m.groups()
            gates.append({"name": json.loads('"%s"' % n), "k": 1, "init": 2, "ins": [int(i)],
                          "arcs": [dict(fmin=int(a), fmax=int(b), smin=int(c), smax=int(d))], "out": int(o)})
            continue
        m = pG.match(ln)
        if m:
            n, k, init, ins, arcs, o = m.groups()
            A = [dict(zip(("fmin", "fmax", "smin", "smax"), map(int, t)))
                 for t in re.findall(r'⟨(\d+), (\d+), (\d+), (\d+)⟩', arcs)]
            gates.append({"name": json.loads('"%s"' % n), "k": int(k), "init": int(init),
                          "ins": [int(x) for x in ins.split(",") if x.strip()], "arcs": A, "out": int(o)})
            continue
        if ln.startswith("  ") and ("⟨" in ln or ln.startswith("  P ")):
            sys.exit("unparsed gate line in %s: %s" % (f, ln[:200]))
allt = open(os.path.join(D, "All.lean")).read()
assert all(g["out"] == i for i, g in enumerate(gates)), "gate i must drive node i"
assert all(len(g["ins"]) == g["k"] == len(g["arcs"]) for g in gates)
mnet = re.search(r'def net : Net := ⟨(\d+), names, gates⟩', allt)
assert int(mnet.group(1)) == len(names), (mnet.group(1), len(names))
mb = re.search(r'def boundary : Boundary :=(.*?)\}', allt, re.S).group(1)
def nums(s): return [int(x) for x in re.findall(r'\d+', s)]
def fld(k):
    return re.search(k + r' := (⟨[^⟩]*⟩|\[[^\]]*\]|\d+)', mb).group(1)
nm = lambda i: names[i]
rst = nums(fld("rst"))[0]
a = fld("a"); b = fld("b"); st = fld("start"); o0 = fld("out0"); pe = fld("pend")
def ch(s):
    x = nums(s); return x[0], x[1], x[2:]
ar, aa, ad = ch(a); br, ba, bd = ch(b); sr, sa, _ = ch(st); orq, oa, od = ch(o0); pr, pa, _ = ch(pe)
assert ar == br == sr == pr
env = nums(fld("env"))
arbs = [{"q": nm(int(q)), "ins": [nm(int(x)) for x in xs.split(",")]}
        for q, xs in re.findall(r'⟨(\d+), \[([\d, ]*)\]⟩', re.search(r'def arbs : List ArbNodes := \[(.*?)\]\n\n', allt, re.S).group(1))]
B = dict(rst=nm(rst), req=nm(ar), a_ack=nm(aa), a_data=[nm(x) for x in ad], b_ack=nm(ba), b_data=[nm(x) for x in bd],
         start_ack=nm(sa), out0_req=nm(orq), out0_ack=nm(oa), out0_data=[nm(x) for x in od], pend_ack=nm(pa))
json.dump({"nodes": names, "gates": gates}, open(onet, "w"))
json.dump({"boundary": B, "env": [nm(x) for x in env], "arbs": arbs}, open(obnd, "w"), indent=1)
print("lean2json: %d nodes, %d gates, %d env nodes, %d arbiters" % (len(names), len(gates), len(env), len(arbs)))
